// undo/logging must be added outside the executor:
record Command(Runnable doIt, Runnable undo) {}

sealed interface Edit { record Insert(int pos, String text) implements Edit {}
                      record Delete(int pos, int len)  implements Edit {} }

void apply(Document doc, Edit e) {
  switch (e) {                                // exhaustive, no default needed
    case Edit.Insert(int pos, String text) -> doc.insert(pos, text);
    case Edit.Delete(int pos, int len)     -> doc.delete(pos, len);
  }
}
